        if (absCenter < absLeft && absCenter < absRight && absCenter < (geomWidth / 4)) {
            return distCenter > 0 ? `Length / 2 + ${fmt(distCenter)}` : `Length / 2 - ${fmt(absCenter)}`;
        }

        if (absRight < absLeft) {
            return `Length - ${fmt(distRight)}`;
        }

        return fmt(distLeft);
    };

    // y is the normalized coordinate (0 to geomHeight).
    const pY = (y: number): string => {
        const distTop = y; // SVG Y=0 is Top
        const distBottom = geomHeight - y;
        const distCenter = y - geomHeight / 2;

        const absTop = Math.abs(distTop);
        const absBottom = Math.abs(distBottom);
        const absCenter = Math.abs(distCenter);

        if (absTop < 0.001) return '0';
        if (absBottom < 0.001) return 'Width';
        if (absCenter < 0.001) return 'Width / 2';

        if (absCenter < absTop && absCenter < absBottom && absCenter < (geomHeight / 4)) {
            return distCenter > 0 ? `Width / 2 + ${fmt(distCenter)}` : `Width / 2 - ${fmt(absCenter)}`;
        }

        if (absBottom < absTop) {
            return `Width - ${fmt(distBottom)}`;
        }

        return fmt(distTop);
    };

    const arePointsClose = (p1: Point, p2: Point) => {
        return Math.abs(p1.x - p2.x) < 0.01 && Math.abs(p1.y - p2.y) < 0.01;
    };

    const dateStr = new Date().toLocaleDateString('ru-RU');

    let script = `// ---------------------------------------------------
// Автоматически сгенерированный скрипт детали
// Дата: ${dateStr}
// Исходные размеры: ${fmt(W)} x ${fmt(H)} мм (Геометрия: ${fmt(geomWidth)}x${fmt(geomHeight)})
// Материал: ${part.material.code} ${part.material.thickness}мм
// ---------------------------------------------------

// Функция построения детали
// Переменные Length и Width соответствуют Ширине и Высоте по лицу
Part.SetMaterial("${part.material.code}", ${part.material.thickness});

// ---------------------------------------------------
// ГЕОМЕТРИЯ
// ---------------------------------------------------
`;

    let currentPos: Point | null = null;

    entities.forEach(entity => {
        if (entity.type === 'LINE') {
            const start = normalize(entity.start);
            const end = normalize(entity.end);

            if (!currentPos || !arePointsClose(currentPos, start)) {
                 script += `\n\nPart.StartContour(${pX(start.x)}, ${pY(start.y)});`;
            }
            script += `\nPart.LineTo(${pX(end.x)}, ${pY(end.y)});`;
            currentPos = end;

        } else if (entity.type === 'LWPOLYLINE') {
            if (entity.vertices.length < 2) return;
            const points = entity.vertices.map(normalize);

            if (!currentPos || !arePointsClose(currentPos, points[0])) {
                script += `\n\nPart.StartContour(${pX(points[0].x)}, ${pY(points[0].y)});`;
            }

            for (let i = 1; i < points.length; i++) {
                script += `\nPart.LineTo(${pX(points[i].x)}, ${pY(points[i].y)});`;
            }
            if (entity.closed) {
                 script += `\nPart.LineTo(${pX(points[0].x)}, ${pY(points[0].y)});`;
                 currentPos = points[0];
            } else {
                 currentPos = points[points.length - 1];
            }

        } else if (entity.type === 'CIRCLE') {
             const c = normalize(entity.center);
             const r = entity.radius;
             const left = { x: c.x - r, y: c.y };
             const right = { x: c.x + r, y: c.y };

             // Circles are usually separate contours
             script += `\n\n// Круглое отверстие`;
             script += `\nPart.StartContour(${pX(left.x)}, ${pY(left.y)});`;
             script += `\nPart.ArcTo(${pX(right.x)}, ${pY(right.y)}, ${pX(c.x)}, ${pY(c.y)}, false);`;
             script += `\nPart.ArcTo(${pX(left.x)}, ${pY(left.y)}, ${pX(c.x)}, ${pY(c.y)}, false);`;
             currentPos = left;

        } else if (entity.type === 'ARC') {
             const d2r = Math.PI / 180;
             const c = normalize(entity.center);
             const r = entity.radius;

             const startRaw = {
                 x: entity.center.x + r * Math.cos(entity.startAngle * d2r),
                 y: entity.center.y + r * Math.sin(entity.startAngle * d2r)
             };
             const endRaw = {
                 x: entity.center.x + r * Math.cos(entity.endAngle * d2r),
                 y: entity.center.y + r * Math.sin(entity.endAngle * d2r)
             };

             const start = normalize(startRaw);
             const end = normalize(endRaw);

             if (!currentPos || !arePointsClose(currentPos, start)) {
                script += `\n\nPart.StartContour(${pX(start.x)}, ${pY(start.y)});`;
             }
             script += `\nPart.ArcTo(${pX(end.x)}, ${pY(end.y)}, ${pX(c.x)}, ${pY(c.y)}, false);`;
             currentPos = end;
        }
    });

    script += `\n\n// ---------------------------------------------------
// ИНСТРУМЕНТ
// ---------------------------------------------------
`;

    // --- PUNCH GENERATION ---
    const groupedPunches = new Map<string, PlacedTool[]>();

    part.punches.forEach(p => {
        // Use :: separator to avoid splitting tool ID (which might contain _)
        const key = `${p.toolId}::${p.rotation.toFixed(2)}`;
        if (!groupedPunches.has(key)) {
            groupedPunches.set(key, []);
        }
        groupedPunches.get(key)?.push(p);
    });

    groupedPunches.forEach((punches, key) => {
        const [toolId, rotationStr] = key.split('::');
        const rotation = parseFloat(rotationStr);
        const tool = tools.find(t => t.id === toolId);
        const toolName = tool ? tool.name : "UNKNOWN_TOOL";

        // Determine tool dimension along the cut for overlap checks
        // If rotation is 0, dimension is Width. If 90, dimension is Height.
        // This is a simplification; for 45 degrees it's more complex.
        const isRotated90 = Math.abs(rotation) % 180 === 90;
        const toolLengthAlongCut = tool ? (isRotated90 ? tool.height : tool.width) : 10;

        // Sort punches spatially
        punches.sort((a, b) => (a.x - b.x) || (a.y - b.y));

        const lines: PlacedTool[][] = [];
        let currentLine: PlacedTool[] = [];

        for (let i = 0; i < punches.length; i++) {
            const curr = punches[i];

            if (currentLine.length === 0) {
                currentLine.push(curr);
                continue;
            }

            const prev = currentLine[currentLine.length - 1];

            const dx = curr.x - prev.x;
            const dy = curr.y - prev.y;
            const dist = Math.sqrt(dx*dx + dy*dy);

            if (dist < 0.001) continue; // Duplicate

            if (currentLine.length === 1) {
                // Forming first segment. 
                // To prevent grouping far-away points as a "line" (which caused the bug),
                // we only group if the distance is reasonable for a pattern or nibble.
                // Let's imply that if dist > 2.5 * ToolSize, it's probably a separate hit, 
                // UNLESS subsequent points confirm a pattern.
                // But the greedy loop approach requires us to commit now.
                // We'll add it to the line for now, but check validity in the Output phase.
                currentLine.push(curr);
            } else {
                const p0 = currentLine[0];
                const p1 = currentLine[1];
                const baseDx = p1.x - p0.x;
                const baseDy = p1.y - p0.y;
                const baseDist = Math.sqrt(baseDx*baseDx + baseDy*baseDy);

                const dot = (baseDx * dx + baseDy * dy) / (baseDist * dist);
                const pitchDiff = Math.abs(dist - baseDist);

                if (Math.abs(dot - 1) < 0.001 && pitchDiff < 0.1) {
                    currentLine.push(curr);
                } else {
                    lines.push(currentLine);
                    currentLine = [curr];
                }
            }
        }
        if (currentLine.length > 0) lines.push(currentLine);

        lines.forEach(line => {
            let isNibbleLine = false;
            let pitch = 0;
            const start = line[0];
            const end = line[line.length - 1];
            const totalDist = Math.sqrt((end.x - start.x)**2 + (end.y - start.y)**2);

            if (line.length >= 3) {
                // 3+ points is definitely a pattern/line
                isNibbleLine = true;
                pitch = totalDist / (line.length - 1);
            } else if (line.length === 2) {
                // 2 points: ambiguous.
                // If distance implies contiguous cutting (overlapping or small gap), treat as NibbleLine.
                // Heuristic: Gap < ToolLength * 1.5
                if (totalDist < toolLengthAlongCut * 1.5) {
                    isNibbleLine = true;
                    pitch = totalDist;
                }
            }

            if (isNibbleLine) {
                script += `\nPart.NibbleLine("${toolName}", ${pX(start.x)}, ${pY(start.y)}, ${pX(end.x)}, ${pY(end.y)}, ${rotation.toFixed(2)}, ${fmt(pitch)});`;
            } else {
                // Separate Strikes
                line.forEach(p => {
                    script += `\nPart.Strike("${toolName}", ${pX(p.x)}, ${pY(p.y)}, ${rotation.toFixed(2)});`;
                });
            }
        });
    });

    return script;
};

